export type FigmaSvgName = keyof typeof FIGMA_SVGS;
export type FigmaImageName = keyof typeof FIGMA_IMAGES;

export function FigmaSvg({
  name,
  width,
  height,
  style,
}: {
  name: FigmaSvgName;
  width?: number | string;
  height?: number | string;
  style?: StyleProp<ViewStyle>;
}) {
  const xml = FIGMA_SVGS[name];
  return <SvgXml xml={xml} {...(width !== undefined ? { width } : {})} {...(height !== undefined ? { height } : {})} style={style} />;
}
